/**
 * What Today's hero says while a notebook is new (uiux
 * 2026-10-22-today-first-visit, M1, M2 and M4, owner-approved 22 Oct 2026).
 *
 * The first visit used to land on "All done for today · 0 to review · 0 new"
 * right after the learner's first session: two zeroes where the app had just
 * done its job. The hero now carries the onboarding's story on: an empty
 * notebook is ready for a word, a first word is in and here is when it comes
 * back, and the next morning names the word that came back.
 *
 * Every date here is worked out by the engine itself (`review` in
 * @lexpad/core) from the word's real state and its notebook's schedule, as if
 * each answer were right, so Boxes and Smart are both told the truth.
 */
import { MAX_BOX, review, type ScheduleSettings, type ScheduleState } from '@lexpad/core';
import { FULL_TODAY_WORDS } from './parts.js';

/**
 * Up to this many words, a notebook with nothing due is still "your first
 * word": the hero shows when it comes back instead of an empty day.
 */
export const FIRST_VISIT_MAX_WORDS = 2;

/** Up to this many due words in a new notebook, the hero names them. */
export const NAMED_DUE_MAX = 3;

/**
 * How many returns the trail shows: the next one and three after it, which
 * on Boxes is tomorrow, 3 days, a week and 3 weeks, the climb to box 5.
 */
export const TRAIL_STOPS = 4;

/** One return of the word, as the trail draws it. */
export interface TrailStop {
  /** The local day it comes back. */
  day: number;
  /** Days since the stop before it (for the first, since today). */
  gap: number;
  /** It reaches the top box with the answer before this stop. */
  top: boolean;
}

/** What the hero is doing. `usual` is the hero as it always was. */
export type HeroMode = 'empty' | 'firstWin' | 'named' | 'usual';

/** The facts the mode is decided from. */
export interface ModeSignals {
  words: number;
  due: number;
  fresh: number;
  backlog: boolean;
  held: number;
  /** A trail could be worked out for the newest started word. */
  trail: boolean;
}

/** Which hero a notebook gets. Pure, for the screen and its tests. */
export function heroMode(s: ModeSignals): HeroMode {
  if (s.words === 0) return 'empty';
  const plain = !s.backlog && s.held === 0 && s.fresh === 0;
  if (plain && s.due === 0 && s.words <= FIRST_VISIT_MAX_WORDS && s.trail) return 'firstWin';
  if (plain && s.due >= 1 && s.due <= NAMED_DUE_MAX && s.words < FULL_TODAY_WORDS) return 'named';
  return 'usual';
}

/**
 * When a word comes back if every answer is right: the next due day, then
 * each return after it, by the notebook's own rules. A word already due is
 * due today.
 */
export function trailFor(
  state: ScheduleState,
  key: string,
  settings: ScheduleSettings,
  today: number,
  stops: number = TRAIL_STOPS,
): TrailStop[] {
  const first = Math.max(state.dueDay, today);
  const out: TrailStop[] = [{ day: first, gap: first - today, top: state.box >= MAX_BOX }];
  let current: ScheduleState = { ...state, dueDay: first };
  while (out.length < stops) {
    const { next } = review(
      current,
      { correct: true, cardType: 'classic', reviewDay: current.dueDay, key },
      settings,
    );
    if (next.dueDay <= current.dueDay) break;
    out.push({ day: next.dueDay, gap: next.dueDay - current.dueDay, top: next.box >= MAX_BOX });
    current = next;
  }
  return out;
}

/**
 * How long a word waits after today's answer, right and wrong, for the named
 * hero's "Remember it, and it waits 3 days. Miss it, and it comes back
 * tomorrow." In days from today.
 */
export function waitsAfter(
  state: ScheduleState,
  key: string,
  settings: ScheduleSettings,
  today: number,
): { right: number; wrong: number } {
  const answer = (correct: boolean): number =>
    review(state, { correct, cardType: 'classic', reviewDay: today, key }, settings).next.dueDay - today;
  return { right: answer(true), wrong: answer(false) };
}
