/**
 * Which parts of Today a learner sees (uiux 2026-10-22-today-first-visit,
 * proposal L1, owner-approved 22 Oct 2026). A newcomer met everything Lexpad
 * can do on the first visit, before having done more than one thing: the
 * owner called it "extremely confusing". Each part now appears once it has
 * something to say about the learner's own words, and never goes again.
 *
 * The thresholds are product definitions of "a notebook with something in
 * it", not limits or tunables the server owns; each is a named constant here
 * with a test, and the hero, the streak, the bell and the + button are
 * always there.
 */

/** The parts that wait for their moment. */
export type TodayPart = 'latest' | 'week' | 'progress' | 'focused' | 'audio' | 'reading' | 'places';

/** Every part, in the order Today draws them. */
export const TODAY_PARTS: readonly TodayPart[] = [
  'latest',
  'focused',
  'audio',
  'places',
  'reading',
  'progress',
  'week',
];

/**
 * "Latest entries" from this many words: with one, the hero's card already
 * shows it, and a strip of one card read as a strip that lost the rest.
 */
export const LATEST_MIN_WORDS = 2;

/** "This week" from the second day with practice: one filled square says nothing yet. */
export const WEEK_MIN_PRACTICE_DAYS = 2;

/**
 * A notebook of this many words is a notebook to practise in parts: the
 * focused-practice tiles and listening join Today here. Below it a "focused"
 * set of one or two words is the whole notebook again.
 */
export const FULL_TODAY_WORDS = 10;

/**
 * The other places to practise and to find words (the games, Decks, "Find the
 * words worth keeping") also open after this many days with practice, for a
 * learner who keeps a small notebook but has made a habit of it.
 */
export const PLACES_MIN_PRACTICE_DAYS = 3;

/** What the parts are decided from: the learner's own facts, read locally. */
export interface PartSignals {
  /** Words in view. */
  words: number;
  /** Local days with at least one answer, counted up to PLACES_MIN_PRACTICE_DAYS. */
  practiceDays: number;
  /** Some word has reached box 3 or beyond: there is progress to show. */
  pastBox2: boolean;
}

/** Whether each part is on Today for these facts. Pure, for the screen and its tests. */
export function todayParts(signals: PartSignals): Record<TodayPart, boolean> {
  const full = signals.words >= FULL_TODAY_WORDS;
  const habit = signals.practiceDays >= PLACES_MIN_PRACTICE_DAYS;
  return {
    latest: signals.words >= LATEST_MIN_WORDS,
    week: signals.practiceDays >= WEEK_MIN_PRACTICE_DAYS,
    progress: signals.pastBox2,
    focused: full,
    audio: full,
    reading: full || habit,
    places: full || habit,
  };
}

/**
 * The parts to mark "New" on this visit: on now and never seen on this
 * device. The first time this runs (`seen` undefined) is the baseline: what
 * an existing learner already had is not new to them.
 */
export function newParts(
  on: Record<TodayPart, boolean>,
  seen: readonly TodayPart[] | undefined,
): TodayPart[] {
  if (seen === undefined) return [];
  return TODAY_PARTS.filter((part) => on[part] && !seen.includes(part));
}

/** What to remember after this visit: everything seen so far, and what is on now. */
export function seenAfter(
  on: Record<TodayPart, boolean>,
  seen: readonly TodayPart[] | undefined,
): TodayPart[] {
  const out = new Set<TodayPart>(seen ?? []);
  for (const part of TODAY_PARTS) if (on[part]) out.add(part);
  return TODAY_PARTS.filter((part) => out.has(part));
}
