/** Everything the Today screen reads, in one local query. */
import {
  boxCounts,
  countWords,
  dayIndex,
  effectiveStreak,
  firstMeaning,
  isDue,
  activeToday as isActiveToday,
  type BoxCounts,
  type Counts,
  type Word,
  newestFirst,
  kindCounts,
  type Kind,
  type PracticeScope,
  LEVELS,
} from '@lexpad/core';
import {
  inView,
  listNotebooks,
  listWords,
  loadConfusions,
  countPracticeDays,
  loadHistory,
  loadSchedule,
  loadSettings,
  loadStreak,
} from '@/db/repo.js';
import { getMeta, type StoredDayStat, type StoredNotebook, type StoredPlanSnapshot } from '@/db/schema.js';
import { localTimeZone } from '@/lib/format.js';
import { cappedDueWords } from '@/features/schedule/capped.js';
import { FIRST_VISIT_MAX_WORDS, NAMED_DUE_MAX, trailFor, waitsAfter, type TrailStop } from './firstVisit.js';
import { FULL_TODAY_WORDS, PLACES_MIN_PRACTICE_DAYS } from './parts.js';

/** How many days the "This week" strip shows. */
export const WEEK_DAYS = 7;

/** One card in the "Latest entries" strip. */
export interface RecentWord {
  id: string;
  headword: string;
  meaning: string;
  /** Due today: the hero's card must not show its meaning before the test. */
  due: boolean;
}

/** The newest started word of a tiny notebook and when it comes back (first visit, M1). */
export interface FirstWordTrail {
  headword: string;
  stops: TrailStop[];
}

/** The due words of a new notebook, named in the hero (day 2, M2). */
export interface NamedDue {
  /** In the order the session asks them. */
  headwords: string[];
  /** For one word: how many days a right and a wrong answer today send it. */
  waits?: { right: number; wrong: number };
}

export interface TodayData {
  notebook: StoredNotebook | undefined;
  counts: Counts;
  /** Oldest first, always exactly WEEK_DAYS long. */
  week: StoredDayStat[];
  streak: number;
  streakActive: boolean;
  /** Topics present in the notebook, most words first. */
  topics: { name: string; count: number }[];
  /** Word counts per CEFR band, A1 to C1 as the prototype shows. */
  levels: { level: string; count: number }[];
  /** Kinds present in the notebook (phrasal verbs, idioms, nouns…), with counts. */
  kinds: { kind: Kind; count: number }[];
  mastered: number;
  today: number;
  /** The six newest entries, for the strip under the hero. */
  recent: RecentWord[];
  /** Words that have been reviewed at least once. */
  started: number;
  /** Cards answered today, for the progress teaser. */
  doneToday: number;
  /** Cards answered over the week the strip shows. */
  weekTotal: number;
  /** How many words sit in each Leitner box, for the teaser bar. */
  boxes: BoxCounts;
  /** How many distinct topics the notebook has. */
  topicCount: number;
  /** The session length the learner chose; 0 means no cap. */
  sessionCap: number;
  /** Which notebooks a session draws from, and how many there are. */
  practiceScope: PracticeScope;
  notebooks: number;
  /**
   * Due words a notebook's daily review limit leaves for tomorrow (SRS v2);
   * `counts.due` is then the ones today asks about.
   */
  held: number;
  /** More is due than today has room for, so new words wait. */
  backlog: boolean;
  /**
   * The soonest day after today a word in view comes back, for "Your words
   * come back tomorrow" when nothing is due (the new learner's journey, M5);
   * undefined when no started word is waiting.
   */
  nextDue: number | undefined;
  /** Some started word in view is not due today: extra practice would keep its box. */
  notDue: boolean;
  /** Local days with any answer, counted up to PLACES_MIN_PRACTICE_DAYS (Today's parts, L1). */
  practiceDays: number;
  /** A tiny notebook's newest started word and its returns, while nothing is due. */
  trail?: FirstWordTrail | undefined;
  /** A new notebook's few due words. */
  named?: NamedDue | undefined;
  /**
   * The plan the learner made in onboarding (meta `planMinutes`) and the new
   * words a day it set (`newPerDay`), for the first visit's plan row; absent
   * for an account that never made one.
   */
  plan?: { minutes: number; newPerDay: number } | undefined;
  /**
   * The account's last plan kept on this device (billing/planSnapshot.ts),
   * read with the page so the trial's chip lands with it on a cold start.
   */
  planSnapshot?: StoredPlanSnapshot | null;
}

/** Reads the whole screen from IndexedDB. */
export async function loadToday(now: Date = new Date()): Promise<TodayData> {
  const timeZone = localTimeZone();
  const today = dayIndex(now, timeZone);
  const { notebooks: viewing, showing: notebook, all: across } = await inView();

  if (!notebook) {
    return {
      notebook: undefined,
      counts: {
        due: 0,
        new: 0,
        starred: 0,
        struggling: 0,
        confusables: 0,
        tricky: 0,
        mastered: 0,
        total: 0,
        unready: 0,
      },
      week: await loadHistory(WEEK_DAYS, timeZone, now),
      streak: 0,
      streakActive: false,
      topics: [],
      levels: [],
      kinds: [],
      mastered: 0,
      today,
      recent: [],
      started: 0,
      doneToday: 0,
      weekTotal: 0,
      boxes: [0, 0, 0, 0, 0],
      topicCount: 0,
      sessionCap: 0,
      practiceScope: 'notebook',
      notebooks: 0,
      held: 0,
      backlog: false,
      nextDue: undefined,
      notDue: false,
      practiceDays: await countPracticeDays(PLACES_MIN_PRACTICE_DAYS),
      planSnapshot: await getMeta('planSnapshot'),
    };
  }

  // Nothing here reads the outbox: it changes with every write and every
  // push, and each change would re-run all of this for a dot. Today watches
  // it on its own (`hasQueued`).
  const [lists, confusions, week, streak, settings, notebooks, practiceDays] = await Promise.all([
    Promise.all(viewing.map((one) => listWords(one.id))),
    loadConfusions(),
    loadHistory(WEEK_DAYS, timeZone, now),
    loadStreak(),
    loadSettings(),
    listNotebooks(),
    countPracticeDays(PLACES_MIN_PRACTICE_DAYS),
  ]);

  const words = lists.flat();
  const { capped, due: dueIds } = await cappedDueWords(viewing, lists, today);
  const counts = { ...countWords(words, today, confusions), due: capped.due };
  const topics = topicsOf(words);
  // One pass for the three facts about started words, rather than a filter each.
  const { started, nextDue } = startedOf(words, today);
  return {
    notebook,
    counts,
    week,
    streak: effectiveStreak(streak, today),
    streakActive: isActiveToday(streak, today),
    topics,
    levels: levelsOf(words),
    kinds: kindCounts(words),
    mastered: counts.mastered,
    today,
    recent: recentOf(words, today),
    started,
    doneToday: week.find((day) => day.day === today)?.reviewed ?? 0,
    weekTotal: week.reduce((sum, day) => sum + day.reviewed, 0),
    boxes: boxCounts(words),
    topicCount: topics.length,
    sessionCap: settings?.sessionCap ?? 0,
    practiceScope: across ? 'all' : 'notebook',
    notebooks: notebooks.length,
    held: capped.held,
    backlog: capped.backlog,
    nextDue,
    notDue: nextDue !== undefined,
    practiceDays,
    plan: await planOf(settings?.newPerDay),
    trail: words.length <= FIRST_VISIT_MAX_WORDS ? await trailOf(words, today) : undefined,
    named:
      words.length < FULL_TODAY_WORDS && capped.due >= 1 && capped.due <= NAMED_DUE_MAX
        ? await namedOf(words, dueIds.flat(), today)
        : undefined,
    planSnapshot: await getMeta('planSnapshot'),
  };
}

/** The onboarding plan, when the learner made one there. */
async function planOf(
  newPerDay: number | undefined,
): Promise<{ minutes: number; newPerDay: number } | undefined> {
  const minutes = await getMeta('planMinutes');
  return minutes === null || newPerDay === undefined ? undefined : { minutes, newPerDay };
}

/**
 * The newest word answered at least once, and when it comes back if every
 * answer is right, by its notebook's own schedule. Only read for a notebook
 * of a word or two.
 */
async function trailOf(words: readonly Word[], today: number): Promise<FirstWordTrail | undefined> {
  const word = [...words]
    .sort(newestFirst)
    .find((one) => one.progress !== undefined && one.progress.reps > 0 && !one.progress.retired);
  if (word?.progress === undefined) return undefined;
  const schedule = await loadSchedule(word.notebookId);
  return { headword: word.headword, stops: trailFor(word.progress, word.id, schedule, today) };
}

/** The due words of a new notebook by name, and for one word what today's answer does. */
async function namedOf(words: readonly Word[], dueIds: readonly string[], today: number): Promise<NamedDue> {
  const byId = new Map(words.map((word) => [word.id, word]));
  const due = dueIds.map((id) => byId.get(id)).filter((word): word is Word => word !== undefined);
  const only = due.length === 1 ? due[0] : undefined;
  if (only?.progress === undefined) return { headwords: due.map((word) => word.headword) };
  const schedule = await loadSchedule(only.notebookId);
  return { headwords: [only.headword], waits: waitsAfter(only.progress, only.id, schedule, today) };
}

/**
 * Words answered at least once, and the soonest day after today one of the
 * words still in practice comes back.
 */
function startedOf(words: readonly Word[], today: number): { started: number; nextDue: number | undefined } {
  let started = 0;
  let nextDue: number | undefined;
  for (const word of words) {
    const progress = word.progress;
    if (progress === undefined) continue;
    if (progress.reps > 0) started += 1;
    if (
      !progress.retired &&
      progress.dueDay > today &&
      (nextDue === undefined || progress.dueDay < nextDue)
    ) {
      nextDue = progress.dueDay;
    }
  }
  return { started, nextDue };
}

/** The newest entries first, as the prototype's strip shows them. */
function recentOf(words: readonly Word[], today: number): RecentWord[] {
  return [...words]
    .sort(newestFirst)
    .slice(0, 6)
    .map((word) => ({
      id: word.id,
      headword: word.headword,
      meaning: firstMeaning(word),
      due: word.progress !== undefined && !word.progress.retired && isDue(word.progress, today),
    }));
}

/** Topics that actually have words, busiest first. */
function topicsOf(words: readonly Word[]): { name: string; count: number }[] {
  const counts = new Map<string, number>();
  for (const word of words) {
    if (word.progress?.retired === true) continue;
    counts.set(word.category, (counts.get(word.category) ?? 0) + 1);
  }
  return [...counts.entries()]
    .map(([name, count]) => ({ name, count }))
    .sort((a, b) => (b.count !== a.count ? b.count - a.count : a.name.localeCompare(b.name)));
}

/** One entry per band, including the empty ones, so the row never reflows. */
function levelsOf(words: readonly Word[]): { level: string; count: number }[] {
  const counts = new Map<string, number>();
  for (const word of words) {
    if (word.progress?.retired === true || word.level === undefined) continue;
    counts.set(word.level, (counts.get(word.level) ?? 0) + 1);
  }
  return LEVELS.map((level) => ({ level, count: counts.get(level) ?? 0 }));
}
